// CPU float mip reuse only. GPU residency, active geometry atlases and returned
// caller snapshots have separate lifetimes and are not counted as this pool.
const defaultBudgetBytes=256*1024*1024;
let owners=new WeakMap(),budgetBytes=defaultBudgetBytes,bytes=0,peakBytes=0,hits=0,misses=0,evictions=0,releases=0,clears=0,uncached=0,collected=0;
const entries=new Map(),finalizer=typeof FinalizationRegistry==='function'?new FinalizationRegistry(token=>{if(entries.has(token)){drop(token);collected++;}}):null;
function weight(chains){const buffers=new Set();let total=0;for(const levels of chains.values())for(const level of levels){const data=level?.data;if(!ArrayBuffer.isView(data)||!(data instanceof Float32Array))throw Error('광선 밉 캐시 자료를 확인하세요.');if(!buffers.has(data.buffer)){buffers.add(data.buffer);total+=data.buffer.byteLength;}}if(!Number.isSafeInteger(total))throw Error('광선 밉 캐시 크기를 확인하세요.');return total;}
function drop(token,evicted=false){if(!entries.delete(token))return;finalizer?.unregister(token);bytes-=token.bytes;token.chains=null;if(evicted)evictions++;}
function trim(required=0){while(entries.size&&bytes+required>budgetBytes)drop(entries.keys().next().value,true);}
export const rayMipCache={
 get(map){const owner=owners.get(map),token=owner?.token;if(!token?.chains){misses++;return;}hits++;entries.delete(token);entries.set(token,true);return {pixels:owner.pixels,version:owner.version,chains:token.chains};},
 set(map,value){const size=weight(value.chains),old=owners.get(map)?.token;if(old)drop(old);if(size>budgetBytes||budgetBytes===0){owners.delete(map);uncached++;return;}trim(size);const token={chains:value.chains,bytes:size};owners.set(map,{pixels:value.pixels,version:value.version,token});entries.set(token,true);finalizer?.register(map,token,token);bytes+=size;peakBytes=Math.max(peakBytes,bytes);},
 delete(map){const owner=owners.get(map);if(owner?.token.chains){drop(owner.token);releases++;}owners.delete(map);}
};
export function rayMipCacheInfo(){return {version:1,scope:'CPU converted float mip cache; excludes active/caller snapshots, geometry/ray atlases, source images, JS overhead and GPU memory',budgetBytes,bytes,peakBytes,entries:entries.size,hits,misses,evictions,releases,clears,uncached,collected,ownerGCCleanup:!!finalizer};}
export function configureRayMipCache({budgetBytes:next}={}){if(!Number.isSafeInteger(next)||next<0)throw Error('광선 밉 캐시 예산은 0 이상의 안전한 정수 바이트여야 해요.');budgetBytes=next;trim();return rayMipCacheInfo();}
export function clearRayMipCache(){for(const token of entries.keys()){finalizer?.unregister(token);token.chains=null;}entries.clear();owners=new WeakMap();bytes=0;clears++;return rayMipCacheInfo();}
export const rayMipCacheContract=Object.freeze({version:1,defaultBudgetBytes,zero:'disable retained CPU conversion reuse; existing caller snapshots remain valid',accounting:'unique Float32 ArrayBuffers per entry, across all color/layout/filter variants; source pixels and GPU/active snapshots excluded',ownership:'weak texture owner; LRU tokens retain only converted level chains, never the texture, image or material',eviction:'least recently used conversion; no mutation or detachment of returned level arrays or pixel data; version/filter/color keys remain authoritative',temporary:'conversion is produced before cache insertion; temporary conversion and active snapshots can exceed the retained-cache budget',cost:'constant-time LRU touch on lookup; level/buffer accounting on changed cache entries only; owner-GC cleanup when supported; no per-frame texture scan or GPU readback',api:'profiler.rayMipCache optional budgetBytes/clear; profiler.read.rayMipCache and profiler panel use the same process pool',remaining:'GPU mip residency/streaming pools and async disk mip IO are independent and remain additional work'});
